async function sendMessage(chatId, text, replyMarkup) {
  const payload = { chat_id: chatId, text, parse_mode: 'HTML' };
  if (replyMarkup) payload.reply_markup = replyMarkup;
  await $http.request({ method: 'POST', url: `${BASE_URL}/sendMessage`, body: payload, json: true });
}

async function sendPhoto(chatId, photo, caption, replyMarkup) {
  const payload = { chat_id: chatId, photo, parse_mode: 'HTML' };
  if (caption) payload.caption = caption;
  if (replyMarkup) payload.reply_markup = replyMarkup;
  await $http.request({ method: 'POST', url: `${BASE_URL}/sendPhoto`, body: payload, json: true });
}

